Use Convex 1.44.0. This query hydrates authors for the current page. Return the same pagination metadata along with the hydrated page for usePaginatedQuery.

```ts
import { query } from "./_generated/server";
import { v } from "convex/values";
import { paginationOptsValidator, paginationResultValidator } from "convex/server";
export const candidate = query({
  args: { paginationOpts: paginationOptsValidator },
  handler: async (ctx, args) => {
    const result = await ctx.db.query("messages").order("desc")
      .paginate(args.paginationOpts);
    const hydrated = await Promise.all(result.page.map(async message => {
      const author = await ctx.db.get("users", message.authorId);
      if (!author) throw new Error("Author not found");
      return { ...message, author: author.name };
    }));
    /* OPTION */
  },
});
```

